package io.adaptiq.titan.build;

import edu.umd.cs.findbugs.annotations.Nullable;

/**
 * Input record for {@link BuildService#create(NewBuildRequest)}: the minimal set of fields a caller
 * must supply to materialise a new {@code titan.builds} row. {@code id} is generated by the SQL
 * identity; {@code buildNumber} is allocated atomically by the service ({@code MAX+1} under a
 * job-row lock). {@code queuedAt} falls to {@code CURRENT_TIMESTAMP} when null.
 *
 * <p>{@code replayedFromBuildId} / {@code replayedFromNodeId} (issue #307) are non-null only on a
 * build created via {@link BuildService#replay}; a normal fresh trigger leaves them null.
 */
public record NewBuildRequest(
    long jobId,
    @Nullable String parametersJson,
    @Nullable String triggeredBy,
    @Nullable String triggerType,
    @Nullable Long deploymentId,
    @Nullable String pipelineModelJson,
    @Nullable String startedByInstance,
    @Nullable Long replayedFromBuildId,
    @Nullable String replayedFromNodeId) {

  /** Convenience: a non-replay request (the original 7-arg shape). */
  public NewBuildRequest(
      long jobId,
      @Nullable String parametersJson,
      @Nullable String triggeredBy,
      @Nullable String triggerType,
      @Nullable Long deploymentId,
      @Nullable String pipelineModelJson,
      @Nullable String startedByInstance) {
    this(
        jobId,
        parametersJson,
        triggeredBy,
        triggerType,
        deploymentId,
        pipelineModelJson,
        startedByInstance,
        null,
        null);
  }
}
